  "Recent jobs": "Letzte Jobs",
  "Open a job for its stages and tables. A failed job that recorded how it started can be retried; a running job cannot be cancelled, because the API has no cancel.": "Öffnen Sie einen Job für seine Phasen und Tabellen. Ein fehlgeschlagener Job, der seinen Start aufgezeichnet hat, kann wiederholt werden; ein laufender Job kann nicht abgebrochen werden, weil die API kein Abbrechen kennt.",
  "No job has run yet.": "Es ist noch kein Job gelaufen.",
  "Runs and jobs": "Läufe und Jobs",
  "Starting runs": "Läufe starten",
  "Start work here and follow it in the job line. Everything below acts on one system at a time.": "Starten Sie hier Arbeit und verfolgen Sie sie in der Jobzeile. Alles unten wirkt jeweils auf ein System.",
  "No system is connected yet. Connect one from the landscape, then start an extraction here.": "Es ist noch kein System verbunden. Verbinden Sie eines über die Landschaft und starten Sie dann hier eine Extraktion.",
  "{title}. They apply from the next analysis run": "{title}. Sie gelten ab dem nächsten Analyselauf",
  "Earlier runs keep the scoring they were scored under.": "Frühere Läufe behalten die Bewertung, unter der sie bewertet wurden.",
  "Dimension weights": "Dimensionsgewichte",
  "The score is each measured dimension times its weight. The weights must add up to 100.": "Der Score ist jede gemessene Dimension mal ihr Gewicht. Die Gewichte müssen zusammen 100 ergeben.",
  "0 to 100": "0 bis 100",
  "The weights add up to 100.": "Die Gewichte ergeben zusammen 100.",
