  "Use the DAMA defaults": "DAMA-Standardwerte verwenden",
  "Score bands": "Score-Bänder",
  "At or above target is on target (go), at or above warning is at risk, below that is failing. Critical marks the line below which an object is failing badly.": "Ab dem Ziel ist es im Ziel (Go), ab der Warnung gefährdet, darunter nicht bestanden. Kritisch markiert die Linie, unter der ein Objekt deutlich durchfällt.",
  "Critical must not exceed warning, and warning must not exceed target.": "Kritisch darf Warnung nicht überschreiten, und Warnung darf Ziel nicht überschreiten.",
  "Score bands saved": "Score-Bänder gespeichert",
  "Save bands": "Bänder speichern",
  "Use the default bands": "Standardbänder verwenden",
  "Cap rule and tolerance": "Deckelungsregel und Toleranz",
  "One critical rule failing beyond its tolerance holds that object at 85; two or more hold it at 70. The caps are fixed. The tolerance says how many failing records count as beyond.": "Eine kritische Regel, die über ihre Toleranz hinaus fehlschlägt, hält das Objekt bei 85; zwei oder mehr halten es bei 70. Die Deckel sind fest. Die Toleranz sagt, wie viele fehlerhafte Datensätze als darüber zählen.",
