  "How long runs, reports and audit rows are kept. Archived runs past the limit are purged for good by the nightly task. Empty means for ever.": "Wie lange Läufe, Berichte und Audit-Zeilen aufbewahrt werden. Archivierte Läufe über der Grenze werden von der nächtlichen Aufgabe endgültig gelöscht. Leer bedeutet für immer.",
