  "Delete all data": "Alle Daten löschen",
  "Removes every run, report and audit row of this organisation, and its stored files, for good. A request issues a token that works after 24 hours, so a mistake can be caught. The purge log keeps the record of the deletion.": "Entfernt jeden Lauf, jeden Bericht und jede Audit-Zeile dieser Organisation sowie ihre gespeicherten Dateien endgültig. Eine Anfrage erzeugt ein Token, das nach 24 Stunden gilt, damit ein Fehler bemerkt werden kann. Das Löschprotokoll behält den Nachweis der Löschung.",
