  "People who signed in through the provider keep their accounts and use a password; those who never set one use Forgot password.": "Personen, die sich über den Anbieter angemeldet haben, behalten ihre Konten und verwenden ein Passwort; wer nie eines festgelegt hat, nutzt „Passwort vergessen“.",
  "OpenID Connect": "OpenID Connect",
  "Use your identity provider, such as Microsoft Entra ID or Okta. People who sign in for the first time get the Viewer role and no access grants; give them access under Users.": "Verwenden Sie Ihren Identitätsanbieter, etwa Microsoft Entra ID oder Okta. Wer sich zum ersten Mal anmeldet, erhält die Rolle Betrachter und keine Zugriffsrechte; vergeben Sie Zugriff unter Benutzer.",
