  "Licence": "Lizenz",
  "What this deployment is licensed for. Plan changes and invoices are handled in Meridian HQ; this deployment keeps its data either way.": "Wofür diese Installation lizenziert ist. Planänderungen und Rechnungen werden in Meridian HQ abgewickelt; diese Installation behält ihre Daten in jedem Fall.",
  "Check with Meridian HQ now": "Jetzt bei Meridian HQ prüfen",
  "The licence": "Die Lizenz",
  "The licence is not valid. Meridian HQ reports status \"{status}\". Renew it in Meridian HQ; module entitlements may be restricted until then.": "Die Lizenz ist ungültig. Meridian HQ meldet den Status \"{status}\". Erneuern Sie sie in Meridian HQ; bis dahin können Modulberechtigungen eingeschränkt sein.",
  "This deployment has not checked its licence with Meridian HQ, so default entitlements apply: no module list, seat count or expiry. It also checks on a schedule.": "Diese Installation hat ihre Lizenz noch nicht bei Meridian HQ geprüft, daher gelten Standardberechtigungen: keine Modulliste, keine Platzzahl und kein Ablaufdatum. Sie prüft auch nach Zeitplan.",
  "The licence has expired. Renew it in Meridian HQ.": "Die Lizenz ist abgelaufen. Erneuern Sie sie in Meridian HQ.",
  "The licence expires in {days} {days, plural, one {day} other {days}}. Renew it in Meridian HQ before then; a renewal shows here after the next check.": "Die Lizenz läuft in {days} {days, plural, one {Tag} other {Tagen}} ab. Erneuern Sie sie vorher in Meridian HQ; eine Verlängerung erscheint hier nach der nächsten Prüfung.",
  "{used} of {seats} seats are in use. {value}": "{used} von {seats} Plätzen sind belegt. {value}",
  "A new invitation fails until a user is suspended or the licence grants more seats.": "Eine neue Einladung schlägt fehl, bis ein Benutzer gesperrt wird oder die Lizenz mehr Plätze gewährt.",
