  "The load file is out and waits for the SAP load. Once it is loaded in SAP, an approver or SAP Basis confirms it here; the next run then checks the records.": "Die Exportdatei ist erstellt und wartet auf den Import in SAP. Sobald sie in SAP geladen ist, bestätigt ein Genehmiger oder SAP Basis das hier; der nächste Lauf prüft dann die Datensätze.",
  "The load could not be confirmed.": "Der Import konnte nicht bestätigt werden.",
  "Load file exported, {records} {records2, plural, one {record} other {records}}": "Exportdatei erstellt, {records} {records2, plural, one {Datensatz} other {Datensätze}}",
