  "Coverage {pct1} is low: part of the records could not be evaluated by at least one rule, so this score may move when extraction improves.": "Die Abdeckung {pct1} ist gering: Ein Teil der Datensätze konnte von mindestens einer Regel nicht ausgewertet werden, daher kann sich dieser Score ändern, wenn die Extraktion besser wird.",
  "; severity weights critical {critical}, high {high}, medium {medium}, low {low}; tolerance {value}% of rows or {rows} rows, as set on each rule; cap rule: {cap_rule}.": "; Schweregradgewichte kritisch {critical}, hoch {high}, mittel {medium}, niedrig {low}; Toleranz {value} % der Zeilen oder {rows} Zeilen, wie für jede Regel festgelegt; Deckelungsregel: {cap_rule}.",
