  "The object could not be read. Check that the API is reachable, then retry.": "Das Objekt konnte nicht gelesen werden. Prüfen Sie, ob die API erreichbar ist, und versuchen Sie es erneut.",
  "Open the landscape": "Landschaft öffnen",
