  "Views of {label}": "Ansichten von {label}",
  "This object has no run on this system.": "Dieses Objekt hat auf diesem System keinen Lauf.",
  "Extracted, not analysed.": "Extrahiert, nicht analysiert.",
  "No run yet. The ruler fills when an analysis scores this object.": "Noch kein Lauf. Das Lineal füllt sich, wenn eine Analyse dieses Objekt bewertet.",
  "The score's working could not be read for this run.": "Die Herleitung des Scores konnte für diesen Lauf nicht gelesen werden.",
  "Measured {raw_score}, the tick on the ruler. ": "Gemessen {raw_score}, die Markierung auf dem Lineal. ",
  "How {score} is made": "Wie {score} entsteht",
  "No failing records are listed for {l} yet. Rows appear when an analysis finds rules with a fixable or suggested value.": "Für {l} sind noch keine fehlerhaften Datensätze aufgeführt. Zeilen erscheinen, wenn eine Analyse Regeln mit einem korrigierbaren oder vorgeschlagenen Wert findet.",
  "Open Work": "Arbeit öffnen",
  "No fix batches for {l} yet. A batch starts when a steward accepts suggested values or imports a filled fix sheet.": "Für {l} gibt es noch keine Korrekturpakete. Ein Paket entsteht, wenn ein Steward vorgeschlagene Werte übernimmt oder ein ausgefülltes Korrekturblatt importiert.",
  "Feature impact for {l} is calculated from the rules that fail. It fills when the impact model has run for this object.": "Die Funktionsauswirkung für {l} wird aus den fehlschlagenden Regeln berechnet. Sie füllt sich, wenn das Auswirkungsmodell für dieses Objekt gelaufen ist.",
  "Open the capping rules": "Deckelnde Regeln öffnen",
  "No process step reads {l} yet. Process readiness fills when a step of the process model reads the fields of the object.": "Noch liest kein Prozessschritt {l}. Die Prozessbereitschaft füllt sich, wenn ein Schritt des Prozessmodells die Felder des Objekts liest.",
  "Lineage fills when a field map is loaded for {l}: it shows where its fields come from and which rules read them.": "Die Herkunft füllt sich, wenn für {l} eine Feldkarte geladen ist: Sie zeigt, woher die Felder kommen und welche Regeln sie lesen.",
  "No glossary terms are linked to {l} yet. A data owner links a term to a field and it appears here.": "Mit {l} sind noch keine Glossarbegriffe verknüpft. Ein Dateneigentümer verknüpft einen Begriff mit einem Feld, und er erscheint hier.",
  "No golden records for {l} yet. A match run creates them from the records that describe the same thing.": "Für {l} gibt es noch keine Golden Records. Ein Abgleichslauf erstellt sie aus den Datensätzen, die dasselbe beschreiben.",
  "Share of their open work that is not yet past its due date.": "Anteil ihrer offenen Arbeit, der noch nicht überfällig ist.",
  " {n} {approvals_waiting, plural, one {batch waits} other {batches wait}} for your approval.": " {n} {approvals_waiting, plural, one {Paket wartet} other {Pakete warten}} auf Ihre Freigabe.",
  "{n} of {n2} {peopleCount, plural, one {person holds} other {people hold}} open work: {n3} {open, plural, one {record} other {records}}, {n4} overdue.{mine}": "{n} von {n2} {peopleCount, plural, one {Person hat} other {Personen haben}} offene Arbeit: {n3} {open, plural, one {Datensatz} other {Datensätze}}, {n4} überfällig.{mine}",
  "The people could not be read. Check that the API is reachable, then retry.": "Die Personen konnten nicht gelesen werden. Prüfen Sie, ob die API erreichbar ist, und versuchen Sie es erneut.",
  "Nobody owns an object or holds work yet. Set an owner on an object, or assign records, and people appear here with their open work.": "Noch besitzt niemand ein Objekt oder hält Arbeit. Legen Sie einen Eigentümer für ein Objekt fest oder weisen Sie Datensätze zu, und Personen erscheinen hier mit ihrer offenen Arbeit.",
