  "The fields are those read by the failing rules of this object in the latest run. Terms are drafted from the rule library with Add terms from the rule library, and a data owner approves each.": "Es sind die Felder, die die fehlschlagenden Regeln dieses Objekts im letzten Lauf lesen. Begriffe werden mit Begriffe aus der Regelbibliothek hinzufügen aus der Regelbibliothek entworfen, und ein Dateneigentümer gibt jeden frei.",
