  "{RULE_LABEL}: {n} {n, plural, one {field} other {fields}}": "{RULE_LABEL}: {n} {n, plural, one {Feld} other {Felder}}",
  "Edit the rules": "Regeln bearbeiten",
  "No survivorship rule is set for this object, so a merge keeps the survivor's value for every field. Add one with Edit the rules.": "Für dieses Objekt ist keine Überlebensregel festgelegt, daher behält ein Zusammenführen für jedes Feld den Wert des überlebenden Datensatzes. Legen Sie eine mit Regeln bearbeiten an.",
  "Survivorship rules by field": "Überlebensregeln nach Feld",
  "Match candidates": "Dublettenkandidaten",
  "1 pair to review": "1 Paar zu prüfen",
  "{waiting} pairs to review": "{waiting} Paare zu prüfen",
  "The match candidates could not be read.": "Die Dublettenkandidaten konnten nicht gelesen werden.",
  "No pair of {label} records is waiting for a steward. Pairs appear when a match run scores two records between the review floor and the auto-merge score.": "Kein Paar von {label}-Datensätzen wartet auf einen Steward. Paare erscheinen, wenn ein Abgleichlauf zwei Datensätze zwischen der Prüfschwelle und dem Score für automatisches Zusammenführen bewertet.",
  "Pairs to review": "Zu prüfende Paare",
