  "Showing the first {pairsCount} of {waiting}, best score first. ": "Die ersten {pairsCount} von {waiting}, bester Score zuerst. ",
  "Show 20 more": "20 weitere anzeigen",
  "The golden records list does not carry the name; open the record": "Die Liste der Golden Records enthält den Namen nicht; öffnen Sie den Datensatz",
  "No survivorship rule is set for this object": "Für dieses Objekt ist keine Überlebensregel festgelegt",
  "The golden records of {label} could not be read.": "Die Golden Records von {label} konnten nicht gelesen werden.",
  "No golden records for {label} yet. A match run groups the records that describe the same thing, scores each pair, and a steward approves the survivor; the golden records and the pairs to review land here.": "Noch keine Golden Records für {label}. Ein Abgleichlauf gruppiert die Datensätze, die dasselbe beschreiben, bewertet jedes Paar, und ein Steward gibt den überlebenden frei; die Golden Records und die zu prüfenden Paare landen hier.",
  "{total} {total2, plural, one {record} other {records}}": "{total} {total2, plural, one {Datensatz} other {Datensätze}}",
  "Golden records of {label}": "Golden Records von {label}",
  "Open golden record {sap_object_key}": "Golden Record {sap_object_key} öffnen",
  "{source_count} sources": "{source_count} Quellen",
  "{pending_issues} open {pending_issues, plural, one {conflict} other {conflicts}}": "{pending_issues} {pending_issues, plural, one {offener Konflikt} other {offene Konflikte}}",
  "No golden record yet for {label}. The pairs above become golden records when a steward merges them.": "Noch kein Golden Record für {label}. Die Paare oben werden zu Golden Records, wenn ein Steward sie zusammenführt.",
  "{from} to {to} of {total}": "{from} bis {to} von {total}",
  "Confidence is the match engine's score for the surviving record. Last merged is when the record last changed. Open conflicts are fields where the sources disagree and no rule has settled it.": "Die Konfidenz ist der Score der Abgleich-Engine für den überlebenden Datensatz. Zuletzt zusammengeführt ist die letzte Änderung des Datensatzes. Offene Konflikte sind Felder, in denen die Quellen voneinander abweichen und keine Regel entschieden hat.",
  "Ledger": "Liste",
  "The ledger of failing records for {label} could not be loaded here. Work lists every record and failing field, ranked by value at risk, with the current value, the suggested value and the decision on the row.": "Die Liste der fehlerhaften Datensätze für {label} konnte hier nicht geladen werden. Arbeit listet jeden Datensatz und jedes fehlerhafte Feld nach gefährdetem Wert, mit aktuellem Wert, vorgeschlagenem Wert und der Entscheidung in der Zeile.",
  "The lineage was saved as an SVG file.": "Die Herkunft wurde als SVG-Datei gespeichert.",
  "This browser cannot save the file.": "Dieser Browser kann die Datei nicht speichern.",
  "Lineage graph, scrollable": "Herkunftsgraph, scrollbar",
  "Lineage of {label}: {counts} tables, {counts2} fields, {counts3} rules, {counts4} S/4 features": "Herkunft von {label}: {counts} Tabellen, {counts2} Felder, {counts3} Regeln, {counts4} S/4-Funktionen",
  "Drawn from the {shown} failing {shown, plural, one {rule} other {rules}} of {label} with the highest value at risk{value}. Features come from the impact model of the current run.": "Gezeichnet aus den {shown} fehlschlagenden {shown, plural, one {Regel} other {Regeln}} von {label} mit dem höchsten gefährdeten Wert{value}. Funktionen stammen aus dem Auswirkungsmodell des aktuellen Laufs.",
  "; {hidden} more are not drawn": "; {hidden} weitere werden nicht gezeichnet",
  "Facts of the node": "Fakten des Knotens",
  "Node facts": "Knotenfakten",
  "Open the feature": "Funktion öffnen",
  "Hover or focus a node to see its facts here. Click a rule or a feature to open it.": "Fahren Sie über einen Knoten oder fokussieren Sie ihn, um hier seine Fakten zu sehen. Klicken Sie auf eine Regel oder Funktion, um sie zu öffnen.",
  "Export as SVG": "Als SVG exportieren",
  "The lineage of {label} could not be read.": "Die Herkunft von {label} konnte nicht gelesen werden.",
  "Lineage for {label} fills when an analysis finds failing rules: it draws the tables and fields those rules read and the S/4HANA features they block or degrade.": "Die Herkunft für {label} füllt sich, wenn eine Analyse fehlschlagende Regeln findet: Sie zeigt die Tabellen und Felder, die diese Regeln lesen, und die S/4HANA-Funktionen, die sie blockieren oder beeinträchtigen.",
  "The S/4 features could not be read for this run, so the graph stops at the rules.": "Die S/4-Funktionen konnten für diesen Lauf nicht gelesen werden, daher endet der Graph bei den Regeln.",
  "Open {l1Id} step {number}": "{l1Id} Schritt {number} öffnen",
