  "The shown score moved only {shownBefore} to {shownAfter}, because the cap holds it at {shownAfter}.": "Der angezeigte Score bewegte sich nur von {shownBefore} auf {shownAfter}, weil die Begrenzung ihn bei {shownAfter} hält.",
