  "{label} has no run history here yet. Each run adds a point once two runs have scored this object.": "{label} hat hier noch keinen Laufverlauf. Jeder Lauf fügt einen Punkt hinzu, sobald zwei Läufe dieses Objekt bewertet haben.",
  "Measured score of {label}, last {pointsCount} runs: {measured} on {label2}, {measured2} on {label3}{value}{value2}.": "Gemessener Score von {label}, letzte {pointsCount} Läufe: {measured} am {label2}, {measured2} am {label3}{value}{value2}.",
