  "The baseline run is {kept}; the newest {n, plural, one {run} other {# runs}} of each system {n, plural, one {is} other {are}} always kept.": "Der Basislauf wird {kept}; die neuesten {n, plural, one {Lauf} other {# Läufe}} jedes Systems {n, plural, one {wird} other {werden}} immer aufbewahrt.",
  "kept": "aufbewahrt",
  "not kept": "nicht aufbewahrt",
  "Runs and reports are kept from 1 to 3650 days, the audit log from 30; empty keeps them for ever.": "Läufe und Berichte werden 1 bis 3650 Tage aufbewahrt, das Änderungsprotokoll ab 30; leer bewahrt sie unbegrenzt auf.",
  "The nightly task applies it, first as a dry run.": "Die nächtliche Aufgabe wendet sie an, zuerst als Probelauf.",
  "Where this deployment keeps its data, what is encrypted at rest, the last backup, and how long each kind of data is kept.": "Wo diese Bereitstellung ihre Daten aufbewahrt, was ruhend verschlüsselt ist, die letzte Sicherung und wie lange jede Art von Daten aufbewahrt wird.",
