  "Empty: no alert on a floor.": "Leer: keine Warnung bei einer Untergrenze.",
  "Automation saved": "Automatisierung gespeichert",
  "Save automation": "Automatisierung speichern",
  "Changing these needs the manage settings permission.": "Diese Einstellungen zu ändern, erfordert die Berechtigung Einstellungen verwalten.",
  "Webhooks": "Webhooks",
  "Managing webhooks": "Webhooks verwalten",
  "{n} active {n, plural, one {webhook} other {webhooks}}. Meridian posts a signed JSON event to each when it happens: ids, names and numbers, never SAP values. A failed post is retried 1, 2, 4 and 8 minutes later and marked failed after 5 attempts.": "{n} {n, plural, one {aktiver Webhook} other {aktive Webhooks}}. Meridian sendet jedem ein signiertes JSON-Ereignis, wenn es eintritt: IDs, Namen und Zahlen, nie SAP-Werte. Ein fehlgeschlagener Versand wird nach 1, 2, 4 und 8 Minuten wiederholt und nach 5 Versuchen als fehlgeschlagen markiert.",
  "Add a webhook": "Webhook hinzufügen",
  "The webhooks could not be read. {detail}": "Die Webhooks konnten nicht gelesen werden. {detail}",
  "No webhook yet. Add one with the URL of a Slack or Teams workflow, or any https endpoint, and the events it should receive.": "Noch kein Webhook. Fügen Sie einen mit der URL eines Slack- oder Teams-Workflows oder eines beliebigen https-Endpunkts und den gewünschten Ereignissen hinzu.",
  "Automation": "Automatisierung",
  "What Meridian does by itself after a configuration change, from stewards' fixes and when a score drops.": "Was Meridian selbst tut: nach einer Konfigurationsänderung, aus den Korrekturen der Stewards und wenn ein Score fällt.",
  "The automation settings": "Die Automatisierungseinstellungen",
  "Only records whose SAP change date is after the last full download of the same objects and scope are read; tables without change dates are read in full. The change log of the download shows what changed, table by table, under Extractions.": "Nur Datensätze, deren SAP-Änderungsdatum nach dem letzten vollständigen Download derselben Objekte und desselben Umfangs liegt, werden gelesen; Tabellen ohne Änderungsdatum werden vollständig gelesen. Das Änderungsprotokoll des Downloads zeigt unter Extraktionen Tabelle für Tabelle, was sich geändert hat.",
