  "Download of {when}": "Download vom {when}",
  "This download": "Dieser Download",
  "The change log of this download could not be read.": "Das Änderungsprotokoll dieses Downloads konnte nicht gelesen werden.",
  "This download has no change log: it was taken before change logs were kept. The next download writes one per table.": "Dieser Download hat kein Änderungsprotokoll: er stammt aus der Zeit, bevor Änderungsprotokolle geführt wurden. Der nächste Download schreibt eines je Tabelle.",
