  "Unchanged": "Unverändert",
  "All tables": "Alle Tabellen",
  "Counts only, never values. A table with SAP change dates is re-read from the last download's date and merged; any other table is read in full. Each is compared with the previous download row by row.": "Nur Anzahlen, nie Werte. Eine Tabelle mit SAP-Änderungsdatum wird ab dem Datum des letzten Downloads neu gelesen und zusammengeführt; jede andere Tabelle wird vollständig gelesen. Jede wird Zeile für Zeile mit dem vorherigen Download verglichen.",
  "Critical rules over tolerance, at most": "Kritische Regeln über der Toleranz, höchstens",
  "{dimension}, at least": "{dimension}, mindestens",
  "Saved. While this contract is breached, no run of the object can be pinned as the baseline.": "Gespeichert. Solange dieser Vertrag verletzt ist, kann kein Lauf des Objekts als Basis angeheftet werden.",
  "Saved. Breaches are shown but nothing is held back.": "Gespeichert. Verstöße werden angezeigt, aber nichts wird zurückgehalten.",
