  "No email after a few minutes? Check spam, or ask your administrator to reset the password for you.": "Nach einigen Minuten keine E-Mail? Prüfen Sie den Spam-Ordner oder bitten Sie Ihren Administrator, das Kennwort für Sie zurückzusetzen.",
