  "Sandbox mode": "Sandbox-Modus",
  "A copy of the latest run to decide on, to rehearse or to train people, with nothing leaving the deployment: notifications, webhooks, digests, report mailouts and SAP write-backs are held back and logged.": "Eine Kopie des letzten Laufs, um darauf zu entscheiden, zu proben oder zu schulen, ohne dass etwas die Installation verlässt: Benachrichtigungen, Webhooks, Digests, Berichtsversand und SAP-Rückschreibungen werden zurückgehalten und protokolliert.",
  "The sandbox state": "Der Sandbox-Zustand",
  "In sandbox": "In der Sandbox",
  "{when}, by {who}": "{when}, von {who}",
  "Runs copied": "Kopierte Läufe",
  "Deliveries held back": "Zurückgehaltene Zustellungen",
  "Exit sandbox mode": "Sandbox-Modus beenden",
  "Enter sandbox mode": "Sandbox-Modus starten",
  "Entering and exiting sandbox mode needs the manage system permission.": "Zum Starten und Beenden des Sandbox-Modus brauchen Sie die Berechtigung System verwalten.",
  "The latest finished run is copied into a sandbox run. Until you exit, decisions land on the copy only and nothing leaves this deployment. Decisions on the real run are refused.": "Der letzte abgeschlossene Lauf wird in einen Sandbox-Lauf kopiert. Bis Sie den Modus beenden, landen Entscheidungen nur auf der Kopie, und nichts verlässt diese Installation. Entscheidungen auf dem echten Lauf werden abgelehnt.",
  "Copy the latest run and enter": "Letzten Lauf kopieren und wechseln",
  "Sandbox mode is on": "Sandbox-Modus ist an",
  "Copied run {run}: {rows}.": "Lauf {run} kopiert: {rows}.",
  "no rows": "keine Zeilen",
  "No finished run to copy: the flag alone is on.": "Kein abgeschlossener Lauf zum Kopieren: Nur der Schalter ist an.",
  "The sandbox runs and every decision made on them are discarded. Deliveries held back are not sent afterwards.": "Die Sandbox-Läufe und alle Entscheidungen darauf werden verworfen. Zurückgehaltene Zustellungen werden danach nicht gesendet.",
  "Discard the sandbox and exit": "Sandbox verwerfen und beenden",
  "Sandbox mode is off": "Sandbox-Modus ist aus",
  "Discarded: {rows}.": "Verworfen: {rows}.",
