  "Every class of {pack}": "Alle Klassen von {pack}",
  "breached": "verletzt",
  "No policy pack is applied. Apply one under Administration, Policy packs.": "Kein Richtlinienpaket ist angewendet. Wenden Sie eines unter Administration, Richtlinienpakete an.",
