  "Failed jobs to triage": "Fehlgeschlagene Jobs zur Triage",
  "{count} open": "{count} offen",
  "No failed job is waiting. A job that fails and is not followed by a success of the same kind lands here.": "Kein fehlgeschlagener Job wartet. Ein Job, der fehlschlägt und auf den kein Erfolg derselben Art folgt, erscheint hier.",
