  "SAP could not be checked.": "SAP konnte nicht geprüft werden.",
  "The batch was not sent to SAP": "Das Paket wurde nicht an SAP gesendet",
  "Sending to SAP needs the approve permission, which your role does not hold.": "Das Senden an SAP erfordert die Berechtigung zum Freigeben, die Ihre Rolle nicht hat.",
  "Check with SAP first.": "Prüfen Sie zuerst mit SAP.",
  "No field of this batch goes by BAPI; deliver it with the load file.": "Kein Feld dieses Pakets wird per BAPI übertragen; liefern Sie es mit der Ladedatei aus.",
  "Live write-back": "Direktes Zurückschreiben",
  "This deployment writes approved values to SAP through its BAPIs. Check with SAP first: it says which fields a BAPI carries and why the others go out with the load file. Nothing is sent by the check.": "Diese Installation schreibt freigegebene Werte über die BAPIs von SAP zurück. Prüfen Sie zuerst mit SAP: Die Prüfung zeigt, welche Felder ein BAPI überträgt und warum die übrigen mit der Ladedatei ausgeliefert werden. Bei der Prüfung wird nichts gesendet.",
  "Checking with SAP needs the apply permission, which your role does not hold.": "Die Prüfung mit SAP erfordert die Berechtigung zum Anwenden, die Ihre Rolle nicht hat.",
  "Check with SAP": "Mit SAP prüfen",
  "Fields by BAPI": "Felder per BAPI",
  "Fields by export": "Felder per Export",
  "Fields checked with SAP": "Mit SAP geprüfte Felder",
  "Sent {sent}, failed {failed}, export only {exportOnly}.": "Gesendet {sent}, fehlgeschlagen {failed}, nur per Export {exportOnly}.",
  "The fields without a BAPI were not sent; deliver them with the load file.": "Die Felder ohne BAPI wurden nicht gesendet; liefern Sie sie mit der Ladedatei aus.",
  "What SAP answered, per record": "Antwort von SAP je Datensatz",
  "{records} {n, plural, one {record is} other {records are}} written to SAP now. Each is checked in a test run first, and SAP commits only a record whose answer holds no error. A committed change cannot be taken back from here.": "{records} {n, plural, one {Datensatz wird} other {Datensätze werden}} jetzt in SAP geschrieben. Jeder wird zuerst in einem Testlauf geprüft, und SAP bucht nur einen Datensatz, dessen Antwort keinen Fehler enthält. Eine gebuchte Änderung kann hier nicht zurückgenommen werden.",
  "Send {records} {n, plural, one {record} other {records}}": "{records} {n, plural, one {Datensatz} other {Datensätze}} senden",
  "Export batch {label} as a load file": "Paket {label} als Ladedatei exportieren",
  "Export load file": "Ladedatei exportieren",
