  "Automatic: table reader": "Automatisch: Tabellenleser",
  "OData through the SAP Gateway": "OData über das SAP Gateway",
  "Reads each table with the table reader below. Needs read access to the tables.": "Liest jede Tabelle mit dem unten gewählten Tabellenleser. Erfordert Lesezugriff auf die Tabellen.",
  "Reads mapped tables through ODP providers (RODPS_REPL). Fields a provider does not carry are reported per table; other tables use the table reader.": "Liest zugeordnete Tabellen über ODP-Provider (RODPS_REPL). Felder, die ein Provider nicht liefert, werden je Tabelle gemeldet; andere Tabellen nutzen den Tabellenleser.",
  "Reads with the table reader. ODP is used only when you choose it, after confirming with SAP that your licence allows it (SAP Note 3255746).": "Liest mit dem Tabellenleser. ODP wird nur verwendet, wenn Sie es auswählen, nachdem Sie mit SAP geklärt haben, dass Ihre Lizenz es erlaubt (SAP-Hinweis 3255746).",
  "Reads through the released APIs your Gateway exposes, such as API_PRODUCT_SRV and API_BUSINESS_PARTNER, with this system's user.": "Liest über die freigegebenen APIs, die Ihr Gateway bereitstellt, etwa API_PRODUCT_SRV und API_BUSINESS_PARTNER, mit dem Benutzer dieses Systems.",
  "Deployment default": "Standard der Installation",
  "Find the first available": "Ersten verfügbaren finden",
