  "Join {from} to {to}: SE16 reads one table at a time, so use SE16H or SQVI": "{from} mit {to} verknüpfen: SE16 liest jeweils eine Tabelle, daher SE16H oder SQVI verwenden",
  "Leave out records whose status in {table} marks them {label}": "Sätze auslassen, deren Status in {table} sie als {label} kennzeichnet",
  "A value of {field} that is not a date also fails": "Ein Wert von {field}, der kein Datum ist, ist ebenfalls fehlerhaft",
  "On the cut-off day itself, records fail when their time is before {cutoff}": "Am Stichtag selbst sind Sätze fehlerhaft, deren Uhrzeit vor {cutoff} liegt",
  "{field} is more than {hours} hours before the run's as-of time": "{field} liegt mehr als {hours} Stunden vor dem Stichzeitpunkt des Laufs",
  "{field} is measured against the run's as-of date": "{field} wird am Stichtag des Laufs gemessen",
