  "About {product}": "Über {product}",
  "Each object is scored on one ruler: six dimensions, a cap when a critical rule fails.": "Jedes Objekt wird auf einem Lineal bewertet: sechs Dimensionen, ein Deckel, wenn eine kritische Regel scheitert.",
  "Every figure is a rule result over your own records, and each one explains its arithmetic.": "Jede Zahl ist ein Regelergebnis über Ihre eigenen Sätze, und jede erklärt ihre Rechnung.",
  "SAP data quality, scored and routed to the people who fix it.": "SAP-Datenqualität, bewertet und an die Menschen weitergeleitet, die sie beheben.",
  "Your SAP data, findings and reports stay in your environment.": "Ihre SAP-Daten, Befunde und Berichte bleiben in Ihrer Umgebung.",
  "Got it": "Verstanden",
  "In the middle: the place you chose, with its one next step.": "In der Mitte: der Ort, den Sie gewählt haben, mit seinem einen nächsten Schritt.",
  "On the left: every system and object with its score. Choose a place to open it.": "Links: jedes System und Objekt mit seinem Score. Wählen Sie einen Ort, um ihn zu öffnen.",
  "On the right: whatever you select, always in the same order. Esc closes it.": "Rechts: was immer Sie auswählen, stets in derselben Reihenfolge. Esc schließt es.",
  "Open the help": "Hilfe öffnen",
