  "{m} and {u}": "{m} und {u}",
  "The bars show how often a field agrees on pairs stewards accepted (dark) and rejected (light). A field that agrees on both separates nothing and earns little weight. Evidence weight is log2 of the two shares.": "Die Balken zeigen, wie oft ein Feld bei Paaren übereinstimmt, die Stewards angenommen (dunkel) und abgelehnt (hell) haben. Ein Feld, das bei beiden übereinstimmt, trennt nichts und erhält wenig Gewicht. Das Beweisgewicht ist der log2 der beiden Anteile.",
  "Calibration needs {n} accepted and {n} rejected steward decisions. Decide more pairs above and the weights are learned from them.": "Die Kalibrierung braucht {n} angenommene und {n} abgelehnte Steward-Entscheidungen. Entscheiden Sie oben weitere Paare, dann werden die Gewichte daraus gelernt.",
