  "An SAP BAdI, middleware or a pipeline posts up to {max} candidate records and gets back, at once, the enabled rules each one fails. A record with a failing critical rule is blocked. Nothing is stored except an audit entry, and no language model sees the records.": "Eine SAP-BAdI, eine Middleware oder eine Pipeline sendet bis zu {max} Kandidatensätze und erhält sofort die aktiven Regeln zurück, die jeder Satz verletzt. Ein Satz mit einer verletzten kritischen Regel wird blockiert. Gespeichert wird nur ein Audit-Eintrag, und kein Sprachmodell sieht die Datensätze.",
