  "Keeping the template": "Vorlage wird gespeichert",
  "Keep the template": "Vorlage speichern",
  "Download a blank template": "Leere Vorlage herunterladen",
  "A blank template lists every field the object's rules read, with its description, whether it is required and its allowed values. The same name again is kept as a new version, with the column corrections carried over.": "Eine leere Vorlage listet jedes Feld, das die Regeln des Objekts lesen, mit Beschreibung, Pflichtkennzeichen und zulässigen Werten. Derselbe Name wird erneut als neue Version gespeichert, die Spaltenkorrekturen werden übernommen.",
