  "The column map could not be saved.": "Die Spaltenzuordnung konnte nicht gespeichert werden.",
  "Choose the field each unresolved column holds. Only fields of this object's tables are offered. A column left open is reported as absent.": "Wählen Sie das Feld, das jede nicht zugeordnete Spalte enthält. Angeboten werden nur Felder der Tabellen dieses Objekts. Eine offene Spalte wird als fehlend gemeldet.",
