  "Where the composite score is heading, when it reaches the go-live target, and which runs the Aletheia engine did not expect. The projection is deterministic; the engine adds what it learned from run-level scores and counts only.": "Wohin sich der Gesamtscore bewegt, wann er das Go-live-Ziel erreicht und welche Läufe die Aletheia-Engine nicht erwartet hat. Die Projektion ist deterministisch; die Engine ergänzt, was sie ausschließlich aus Scores und Zählwerten auf Laufebene gelernt hat.",
