  "Which runs fell out of line and which rules and dimensions moved the composite score, each with its evidence. The results are deterministic; the Aletheia engine adds its own reasoning from run-level scores and counts only.": "Welche Läufe aus der Reihe fielen und welche Regeln und Dimensionen den Gesamtwert bewegten, jeweils mit Nachweis. Die Ergebnisse sind deterministisch; die Aletheia-Engine ergänzt ihre eigene Schlussfolgerung allein aus Werten und Anzahlen je Lauf.",
