  "Band low": "Band unten",
  "Band high": "Band oben",
  "The baseline runs did not vary, so no z can be computed. Any move past the minimum spread is a break.": "Die Basisläufe schwankten nicht, daher lässt sich kein z berechnen. Jede Bewegung über die Mindeststreuung hinaus ist ein Bruch.",
  "Robust z {z}: the observed value is {z} scaled MADs from the baseline median. A break needs at least {k}.": "Robustes z {z}: Der beobachtete Wert liegt {z} skalierte MADs vom Basismedian entfernt. Ein Bruch braucht mindestens {k}.",
  "Robust z of at least {z}: the baseline runs could not be read, so the spread comes from the stored band. A break needs at least {k}.": "Robustes z von mindestens {z}: Die Basisläufe waren nicht lesbar, daher stammt die Streuung aus dem gespeicherten Band. Ein Bruch braucht mindestens {k}.",
  "Median {m}, MAD {mad}, scaled MAD {s} (MAD times 1.4826).": "Median {m}, MAD {mad}, skalierte MAD {s} (MAD mal 1,4826).",
  "The band was widened to the minimum spread: the baseline runs alone vary less than that.": "Das Band wurde auf die Mindeststreuung verbreitert: Die Basisläufe allein schwanken weniger.",
