  "A run ends in error.": "Ein Lauf endet mit einem Fehler.",
  "The SLA sweep finds work past its acknowledge or resolve time.": "Die SLA-Prüfung findet Arbeit, deren Bestätigungs- oder Lösungszeit überschritten ist.",
  "Firewall rejections": "Firewall-Ablehnungen",
  "The data quality firewall blocks records at entry. At most one message per object every 15 minutes.": "Die Datenqualitäts-Firewall blockiert Datensätze bei der Erfassung. Höchstens eine Nachricht pro Objekt alle 15 Minuten.",
  "Configured": "Konfiguriert",
  "Set MERIDIAN_SLACK_WEBHOOK_URL or MERIDIAN_TEAMS_WEBHOOK_URL in the server environment and restart Meridian. The address is a secret and is never shown here.": "Setzen Sie MERIDIAN_SLACK_WEBHOOK_URL oder MERIDIAN_TEAMS_WEBHOOK_URL in der Serverumgebung und starten Sie Meridian neu. Die Adresse ist geheim und wird hier nie angezeigt.",
  "Chat alerts saved": "Chat-Benachrichtigungen gespeichert",
