  "Chat alerts": "Chat-Benachrichtigungen",
  "Counts and a link into Meridian go to a Slack or Teams channel, never record values.": "Anzahlen und ein Link in Meridian gehen an einen Slack- oder Teams-Kanal, nie Datensatzwerte.",
  "The chat alert settings": "Die Einstellungen für Chat-Benachrichtigungen",
  "Check that each email domain has a mail server": "Prüfen, ob jede E-Mail-Domain einen Mailserver hat",
  "Asks this site's own DNS resolver, once per domain, at the next run. Only the domain is asked, never the address. When the resolver does not answer, no address fails.": "Fragt beim nächsten Lauf den eigenen DNS-Resolver dieses Standorts, einmal je Domain. Gefragt wird nur die Domain, nie die Adresse. Antwortet der Resolver nicht, schlägt keine Adresse fehl.",
  "Mail server check on from the next run": "Mailserver-Prüfung ab dem nächsten Lauf an",
