  "Why it fails": "Warum er fehlschlägt",
  "{n, plural, one {# proposed fix waits} other {# proposed fixes wait}} in the cleansing queue.": "{n, plural, one {# vorgeschlagene Korrektur wartet} other {# vorgeschlagene Korrekturen warten}} in der Bereinigungswarteschlange.",
  "Contact verification": "Kontaktprüfung",
  "Email syntax and disposable domains, phone numbers by country, and postal codes, cities and regions against the uploaded postal list. Everything runs on this site; no address leaves it.": "E-Mail-Syntax und Wegwerf-Domains, Telefonnummern nach Land sowie Postleitzahlen, Orte und Regionen gegen die hochgeladene Postliste. Alles läuft an diesem Standort; keine Adresse verlässt ihn.",
  "The contact verification results": "Die Ergebnisse der Kontaktprüfung",
  "Mail server check": "Mailserver-Prüfung",
  "No contact results yet. They appear after the next run of business partner, customer or Employee Central.": "Noch keine Kontaktergebnisse. Sie erscheinen nach dem nächsten Lauf von Geschäftspartner, Kunde oder Employee Central.",
  "Postal codes: a CSV with the columns country, postcode (the SAP country key), and optionally city and region, so address rules also check each record's city and region against its postal code. Bank codes: the licensed SWIFT BIC directory as CSV, BIC in the first column. An upload replaces the system's current list.": "Postleitzahlen: eine CSV mit den Spalten country, postcode (der SAP-Länderschlüssel) und optional city und region, damit Adressregeln auch Ort und Region jedes Datensatzes gegen seine Postleitzahl prüfen. Bankleitzahlen: das lizenzierte SWIFT-BIC-Verzeichnis als CSV, BIC in der ersten Spalte. Ein Upload ersetzt die aktuelle Liste des Systems.",
  "Email, phone and address checks per rule, each failing record with its reason, and the mail server check.": "E-Mail-, Telefon- und Adressprüfungen je Regel, jeder fehlerhafte Datensatz mit seinem Grund, und die Mailserver-Prüfung.",
