  "The link stops working at once. Anyone who opens it afterwards sees nothing; to share the page again, make a new link.": "Der Link funktioniert sofort nicht mehr. Wer ihn danach öffnet, sieht nichts; um die Seite erneut zu teilen, erstellen Sie einen neuen Link.",
  "End the out of office of {from_name}": "Abwesenheit von {from_name} beenden",
