  "This request is cancelled: its approval stops and nothing from it is sent to SAP.": "Diese Anfrage wird storniert: Ihre Genehmigung endet und nichts daraus wird an SAP gesendet.",
  "The SLA policy for {what} is removed. Records that start their clock from now on use the default days.": "Die SLA-Richtlinie für {what} wird entfernt. Datensätze, deren Frist ab jetzt beginnt, verwenden die Standardtage.",
