  "The workbook lists every failing record of run {n} with the rule, the field and the value to correct. Fix the values in Excel and upload the workbook in the next step.": "Die Arbeitsmappe listet jeden fehlerhaften Datensatz von Lauf {n} mit Regel, Feld und zu korrigierendem Wert. Korrigieren Sie die Werte in Excel und laden Sie die Mappe im nächsten Schritt hoch.",
