  "Workbook scope": "Umfang der Arbeitsmappe",
  "One workbook per owner": "Eine Arbeitsmappe je Verantwortlichem",
  "Choosing a smaller workbook or one per owner is not offered by the server yet; the workbook holds every failing record.": "Eine kleinere Mappe oder eine Mappe je Verantwortlichem bietet der Server noch nicht an; die Mappe enthält jeden fehlerhaften Datensatz.",
