  "What is in the workbook": "Was in der Arbeitsmappe steht",
  "One sheet per table. Each row is a record that fails at least one rule; the failing fields are marked and the rule and its description are beside them. Change only the values; keep the key columns as they are, so Meridian can match each row to its record.": "Ein Blatt je Tabelle. Jede Zeile ist ein Datensatz, der mindestens eine Regel verletzt; die fehlerhaften Felder sind markiert, Regel und Beschreibung stehen daneben. Ändern Sie nur die Werte und lassen Sie die Schlüsselspalten unverändert, damit Meridian jede Zeile ihrem Datensatz zuordnen kann.",
