  "Files from the corrected records. LSMW, BAPI and IDoc layouts are review only: check them before you rely on them.": "Dateien aus den korrigierten Datensätzen. LSMW-, BAPI- und IDoc-Layouts dienen nur zur Prüfung: Prüfen Sie sie, bevor Sie sich darauf verlassen.",
