  "LSMW, BAPI, IDoc: review only": "LSMW, BAPI, IDoc: nur zur Prüfung",
  "The workbook flow lives on the Analysis tab, where you upload the target team's template and download your data in its columns.": "Der Arbeitsmappen-Ablauf liegt auf dem Reiter Analyse. Dort laden Sie die Vorlage des Zielteams hoch und laden Ihre Daten in deren Spalten herunter.",
